{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "loan_summary_image",
        "loan_summary_section",
        "tradeoff_analysis_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Austin Mortgage Comparison Analysis",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis compares two fixed-rate mortgage options for a $450,000 loan, evaluating the trade-offs between monthly cash flow and total long-term interest savings.",
        "variant": "body"
      },
      "children": []
    },
    "loan_summary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Austin_Skyline_2019.jpg/1200px-Austin_Skyline_2019.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "loan_summary_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "loan_summary_header_stack",
        "loan_summary_table"
      ]
    },
    "loan_summary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "loan_summary_icon",
        "loan_summary_title"
      ]
    },
    "loan_summary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/house.svg"
      },
      "children": []
    },
    "loan_summary_title": {
      "type": "Text",
      "props": {
        "text": "Loan Performance Summary",
        "variant": "h2"
      },
      "children": []
    },
    "loan_summary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "metric",
            "label": "Metric"
          },
          {
            "key": "optionA",
            "label": "Option A (30-Year)"
          },
          {
            "key": "optionB",
            "label": "Option B (15-Year)"
          }
        ],
        "rows": [
          {
            "metric": "Interest Rate",
            "optionA": "6.50%",
            "optionB": "5.80%"
          },
          {
            "metric": "Monthly Principal + Interest",
            "optionA": "$2,844",
            "optionB": "$3,749"
          },
          {
            "metric": "Total Interest Paid",
            "optionA": "$573,840",
            "optionB": "$224,820"
          },
          {
            "metric": "Total Cost of Loan",
            "optionA": "$1,023,840",
            "optionB": "$674,820"
          },
          {
            "metric": "Equity Build-Up",
            "optionA": "Slow",
            "optionB": "Accelerated"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "metric",
        "highlightColumns": [
          "optionA",
          "optionB"
        ],
        "numericColumns": [
          "optionA",
          "optionB"
        ]
      },
      "children": []
    },
    "tradeoff_analysis_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "tradeoff_analysis_title",
        "tradeoff_cashflow",
        "tradeoff_savings",
        "tradeoff_conclusion"
      ]
    },
    "tradeoff_analysis_title": {
      "type": "Text",
      "props": {
        "text": "Financial Trade-off Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "tradeoff_cashflow": {
      "type": "Text",
      "props": {
        "text": "Monthly Cash Flow: Option A provides a significantly lower monthly payment, saving you $905 per month compared to Option B. This is ideal for homeowners who prioritize current lifestyle flexibility or want to invest the surplus in higher-yielding assets.",
        "variant": "body"
      },
      "children": []
    },
    "tradeoff_savings": {
      "type": "Text",
      "props": {
        "text": "Long-term Savings: Option B results in a massive $349,020 reduction in total interest paid. By choosing the 15-year term, you pay off the house in half the time and secure a lower interest rate, maximizing net worth over the long run.",
        "variant": "body"
      },
      "children": []
    },
    "tradeoff_conclusion": {
      "type": "Text",
      "props": {
        "text": "Conclusion: Choose Option A if you need lower monthly obligations to manage your debt-to-income ratio. Choose Option B if you have a high stable income and want to be debt-free much faster while saving hundreds of thousands in interest.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_title",
        "mortgage_calculator_button",
        "austin_market_trends_button"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "mortgage_calculator_button": {
      "type": "Button",
      "props": {
        "label": "Mortgage Calculator"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bankrate.com/mortgages/mortgage-calculator/"
          }
        }
      },
      "children": []
    },
    "austin_market_trends_button": {
      "type": "Button",
      "props": {
        "label": "Austin Market Trends"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.abor.com/market-statistics"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title",
        "cfpb_source_button",
        "freddie_mac_source_button"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "cfpb_source_button": {
      "type": "Button",
      "props": {
        "label": "CFPB Mortgage Resources"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.consumerfinance.gov/consumer-tools/mortgages/"
          }
        }
      },
      "children": []
    },
    "freddie_mac_source_button": {
      "type": "Button",
      "props": {
        "label": "Freddie Mac Mortgage Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.freddiemac.com/homebuyers"
          }
        }
      },
      "children": []
    }
  }
}
